func longestConsecutive(nums []int) int {
    set := make(map[int]bool, len(nums))
    for _, v := range nums {
        set[v] = true
    }
    best := 0
    for v := range set {
        // 只从序列起点开始扩展，保证总体 O(n)
        if set[v-1] {
            continue
        }
        length := 1
        for set[v+length] {
            length++
        }
        if length > best {
            best = length
        }
    }
    return best
}
